def components(g):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and (i,j) not in seen:
                col=g[i][j]; stack=[(i,j)]; cells=[]
                seen.add((i,j))
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                out.append((col,cells))
    return out

def is_outline(cells):
    ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
    t,b,l,r=min(ys),max(ys),min(xs),max(xs)
    border={(y,x) for y in (t,b) for x in range(l,r+1)}|{(y,x) for x in (l,r) for y in range(t,b+1)}
    return set(cells)==border and len(cells)==len(border)

def extract(g):
    return [(col,cells,is_outline(cells)) for col,cells in components(g)]

def f(g):
    H,W=len(g),len(g[0])
    out=[[0]*W for _ in range(H)]
    shapes=extract(g)
    outlines=[s for s in shapes if s[2]]; pluses=[s for s in shapes if not s[2]]
    # gravity up for outlines, order by top row
    for col,cells,_ in sorted(outlines,key=lambda s:min(c[0] for c in s[1])):
        ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
        t,b,l,r=min(ys),max(ys),min(xs),max(xs)
        hgt=b-t+1
        placed=0
        for top in range(0,t+1):
            cand=[(y-top,x) for y,x in cells]
            # no overlap with out and doesn't jump over? gravity: lowest position with no overlap
            if all(out[y][x]==0 for y,x in cand): placed=top
        for y,x in cells: out[y-placed][x]=col
    for col,cells,_ in sorted(pluses,key=lambda s:min(c[0] for c in s[1])):
        ys=[c[0] for c in cells]
        b=max(ys); hgt=b-min(ys)+1
        placed=0
        for bot in range(H-1,b-1,-1):
            cand=[(y+(bot-b),x) for y,x in cells]
            if all(0<=y<H and out[y][x]==0 for y,x in cand): placed=bot-b
        for y,x in cells: out[y+placed][x]=col
    return out

